  Definition rfin (s : rstate) (T : Z) : Prop :=
    r_remaining s = 1 /\ r_charnum s = maxSV + 1 /\ 0 <= r_ip s /\ 0 <= r_bitCount s <= 32 /\
    8 * r_ip s + r_bitCount s = T /\ rncrel (r_nc s) (maxSV + 1).

  Lemma to_short_small c : -32768 <= c <= 32767 -> to_short c = c.
Proof.
