  (* [comment removed for export] *)
  Lemma rloop_ok f : forall s a,
    ainv nc maxSV tableLog a -> a_sym a <= maxSV -> rrel s a ->
    let AF := arun nc maxSV f (astep nc maxSV a) in
    acond maxSV AF = false ->
    a_T AF <= 8 * hbSize -> B mod 2^(a_T AF) = a_N AF ->
