  Theorem read_body8_ok :
    let TF := a_T (afinal nc maxSV tableLog) in
    let NF := a_N (afinal nc maxSV tableLog) in
    TF <= 8 * hbSize -> B mod 2^TF = NF ->
    exists ncF, read_ncount_body8 buf maxSV1 nc0 = Ok (ncF, maxSV, tableLog, (TF + 7) / 8) /\
                rncrel ncF (maxSV + 1).
